-- chair-step: canonicalization lane 5 — assignment.item/attempt get organization_id NOT NULL (backfilled from the parent session) and lose the redundant platform_admin_only policy; the legacy touch triggers give way to _touch_row
-- lane: canonicalization lane 5 — batch 2, the assignment engine (aidream assignment_engine/store.py).
-- assignment.session: base updated_by / version / deleted_at / visibility (default 'internal' —
--   organization, the doctrine default), _touch_row + _stamp_actor replace the bespoke
--   assignment.touch_updated_at trigger; rules regenerated by iam.apply_rls (entity).
-- assignment.item / assignment.attempt (components; composition edges item->assignment_session,
--   attempt->item already registered): organization_id added and backfilled by the NAMED rule
--   "the parent session's organization" (attempt via item via session), then NOT NULL + FK +
--   covering index; attempt gets created_at (backfilled from started_at). The aidream writer
--   (assignment_engine/store.py) passes organization_id on both inserts in the same change.
--   platform_admin_only (ALL, platform admins) is dropped: platform_admin_read keeps admin reads,
--   and the generated component rules defer to the session, so its owner and org now read too.
set lock_timeout = '2s';

-- ── session ──────────────────────────────────────────────────────────────────
alter table assignment.session add column if not exists updated_by uuid;
alter table assignment.session add column if not exists version int not null default 1;
alter table assignment.session add column if not exists deleted_at timestamptz;
alter table assignment.session add column if not exists visibility platform.visibility not null default 'internal';
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'session_updated_by_fk' and conrelid = 'assignment.session'::regclass) then
    alter table assignment.session add constraint session_updated_by_fk foreign key (updated_by) references iam.users(id);
  end if;
end $$;
create index if not exists session_updated_by_idx on assignment.session (updated_by);

-- ── item ─────────────────────────────────────────────────────────────────────
alter table assignment.item add column if not exists organization_id uuid;
update assignment.item i set organization_id = s.organization_id
  from assignment.session s where s.id = i.session_id and i.organization_id is null;
alter table assignment.item alter column organization_id set not null;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'item_org_fk' and conrelid = 'assignment.item'::regclass) then
    alter table assignment.item add constraint item_org_fk foreign key (organization_id) references iam.organizations(id);
  end if;
end $$;
create index if not exists item_organization_id_idx on assignment.item (organization_id);

-- ── attempt ──────────────────────────────────────────────────────────────────
alter table assignment.attempt add column if not exists organization_id uuid;
alter table assignment.attempt add column if not exists created_at timestamptz;
update assignment.attempt a set organization_id = i.organization_id
  from assignment.item i where i.id = a.item_id and a.organization_id is null;
update assignment.attempt set created_at = started_at where created_at is null;
alter table assignment.attempt alter column created_at set default now();
alter table assignment.attempt alter column created_at set not null;
alter table assignment.attempt alter column organization_id set not null;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'attempt_org_fk' and conrelid = 'assignment.attempt'::regclass) then
    alter table assignment.attempt add constraint attempt_org_fk foreign key (organization_id) references iam.organizations(id);
  end if;
end $$;
create index if not exists attempt_organization_id_idx on assignment.attempt (organization_id);

-- ── triggers: the shared pair replaces the bespoke touch ─────────────────────
drop trigger if exists assignment_session_touch_updated_at on assignment.session;
drop trigger if exists assignment_item_touch_updated_at on assignment.item;
drop trigger if exists assignment_attempt_touch_updated_at on assignment.attempt;
drop function if exists assignment.touch_updated_at();
drop trigger if exists _touch_row on assignment.session;
drop trigger if exists _stamp_actor on assignment.session;
create trigger _touch_row before insert or update on assignment.session for each row execute function platform._touch_row();
create trigger _stamp_actor before insert or update on assignment.session for each row execute function platform._stamp_actor();
drop trigger if exists _touch_row on assignment.item;
create trigger _touch_row before insert or update on assignment.item for each row execute function platform._touch_row();
drop trigger if exists _touch_row on assignment.attempt;
create trigger _touch_row before insert or update on assignment.attempt for each row execute function platform._touch_row();

update platform.entity_types set has_soft_delete = true where token = 'assignment_session';

-- ── access rules ─────────────────────────────────────────────────────────────
drop policy if exists platform_admin_only on assignment.item;
drop policy if exists platform_admin_only on assignment.attempt;
select iam.apply_rls('assignment', 'session', 'assignment_session', 'entity');
select iam.apply_rls('assignment', 'item', 'item', 'component');
select iam.apply_rls('assignment', 'attempt', 'attempt', 'component');

do $$ begin
  if exists (select 1 from assignment.item where organization_id is null) then raise exception 'item: null organization_id'; end if;
  if exists (select 1 from assignment.attempt where organization_id is null) then raise exception 'attempt: null organization_id'; end if;
  if (select count(*) from pg_policy where polname = 'platform_admin_read'
        and polrelid in ('assignment.session'::regclass, 'assignment.item'::regclass, 'assignment.attempt'::regclass)) <> 3 then
    raise exception 'platform_admin_read missing on an assignment table';
  end if;
end $$;
